def gc_content(seq: str) -> float:
    """Fraction of G and C bases."""
    gc: int = 0
    for ch in seq:
        if ch == "G" or ch == "C":
            gc += 1
    if len(seq) == 0:
        return 0.0
    return gc / len(seq)

